// 导出所有单词的扁平化列表（词根词 + 补充词，用于搜索和练习）
function getAllWords(): FlatWord[] {
  const words = [];
  const seen = new Set();
  CET4_WORDS.forEach(rootGroup => {
    rootGroup.words.forEach(w => {
      const key = w.word.toLowerCase();
      if (seen.has(key)) return;
      seen.add(key);
      words.push({
        word: w.word,
        phonetic: w.phonetic,
        meaning: w.meaning,
        root: rootGroup.root,
        rootMeaning: rootGroup.meaning,
        prefix: w.prefix,
        suffix: w.suffix
      });
    });
  });
  EXTRA_WORDS.forEach(w => {
    const key = w.word.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    words.push({
      word: w.word,
      phonetic: w.phonetic,
      meaning: w.meaning,
      root: "",
      rootMeaning: "",
      prefix: "",
      suffix: ""
    });
  });
  return words;
}

export { CET4_WORDS, EXTRA_WORDS, PREFIXES, SUFFIXES, getAllWords };
